 INSERT INTO personal_workout_models(user_id,name,origin,source_key,source_payload) VALUES(u,f->>'key','PROGRAM',f->>'key',f->'source') RETURNING id INTO model;
 p:=week_composer_prescription_preview_v1(u,d,g);
 a:=week_plan_personal_program_v1(model,current_date,d,CASE WHEN env='OUTDOOR' THEN 'RUBBER' ELSE NULL END);
 IF a->>'status'<>'SAVED' THEN RAISE EXCEPTION 'Save failure % %',f->>'key',a; END IF;
 item:=(a->>'plan_item_id')::uuid;
 -- A refused inventory must leave the saved plan available for the next valid check-in.
 BEGIN
 c:=week_compile_composer_day_j_v1(u,item,current_date,6,ARRAY['Aucune'],ARRAY[]::text[],env);
 RAISE EXCEPTION 'QA_EXPECTED_INCOMPATIBILITY_%',c->>'status';
 EXCEPTION WHEN OTHERS THEN
 IF SQLERRM NOT LIKE 'COMPOSER_EXERCISE_INCOMPATIBLE_%' THEN RAISE; END IF;
 END;
 c:=week_compile_composer_day_j_v1(u,item,current_date,6,ARRAY['Aucune'],g,env);
 IF c->>'status'<>'READY' THEN RAISE EXCEPTION 'Compile % %',f->>'key',c; END IF;
 sid:=(c->>'session_id')::uuid;
 FOR x IN SELECT ex FROM jsonb_array_elements(p->'blocks') b CROSS JOIN LATERAL jsonb_array_elements(b->'exercises') ex LOOP
 SELECT prescription_json INTO a FROM workout_session_exercises WHERE session_id=sid AND exercise_id=x->>'id';
 IF a IS DISTINCT FROM x->'prescription_json' THEN RAISE EXCEPTION 'Mismatch % %',f->>'key',x->>'id'; END IF; END LOOP;
 results:=results||jsonb_build_array(jsonb_build_object('phase',f->>'key','minutes',p->'duration_minutes','status',c->>'status','rows',(SELECT count(*) FROM workout_session_exercises WHERE session_id=sid)));
 RAISE SQLSTATE 'Z0001';
 EXCEPTION WHEN SQLSTATE 'Z0001' THEN NULL; END;
END LOOP;
IF jsonb_array_length(results)<>6 THEN RAISE EXCEPTION 'Expected six';END IF;
PERFORM set_config('ugerod.qa_program',results::text,true);
END $qa$;
